def on_tick(market, account, state):
    symbol = "AAPL"
    target = 2
    book = market[symbol]
    position = account["positions"][symbol]["position"]

    # Replace the previous quote on each completed minute.
    actions = [
        {"type": "CANCEL", "orderId": order["id"]}
        for order in account["orders"]
        if order["symbol"] == symbol and order["strategyId"] == account["strategyId"]
    ]

    if position < target:
        actions = actions + [{
            "type": "LIMIT", "symbol": symbol, "side": "BUY",
            "quantity": 1, "limitPrice": book["bids"][0]["price"]
        }]
    elif position > 0:
        actions = actions + [{
            "type": "LIMIT", "symbol": symbol, "side": "SELL",
            "quantity": 1, "limitPrice": book["asks"][0]["price"]
        }]

    state["last_position"] = position
    return actions

